effect.shader:
float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    // A faixa sobe pela tela ao longo do tempo (fract mantém dentro de [0, 1]).
    float centroDaFaixa = fract(1.0 - acTime * speed);

    // Distância do pixel à faixa, em y.
    float d = abs(acScreenNorm.y - centroDaFaixa);

    // Está dentro da faixa? (com transição suave nas bordas)
    float meiaAltura = bandHeight * 0.5;
    float suavidade = meiaAltura * max(softEdges, 1e-4);
    float dentro = 1.0 - smoothstep(meiaAltura - suavidade, meiaAltura + suavidade, d);

    // Deslocamento horizontal da faixa (modulado por seno pra "enrolar").
    float onda = sin(acScreenNorm.y * 60.0 - acTime * 20.0);
    float dx = displaceAmount * dentro * onda;

    vec2 uv = acScreenNorm + vec2(dx, 0.0);
    vec4 cor = texture(inputImg, uv);

    // Chuveiro sobreposto só na faixa.
    float ruido = hash2(acScreenNorm * 800.0 + vec2(acTime * 90.0)) - 0.5;
    cor.rgb += vec3(ruido) * noiseAmount * dentro;

    cor.rgb = clamp(cor.rgb, 0.0, 1.0);
    fragColor = cor;
}
